package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.StatementRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final StatementRepository statements;
    private final SheetService sheets;
    private final RollupService rollups;
    private final PeriodService periods;
    private final SettingsService settings;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
            StatementRepository statements, SheetService sheets, RollupService rollups, PeriodService periods,
            SettingsService settings, Audit audit) {
        this.periods = periods;
        this.settings = settings;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.statements = statements;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /**
     * Add a claim for a person; without a date it is dated the sheet's today. One dated in a closed
     * period is refused, as is a correction (a negative amount) that does not name a settled claim of
     * the same person.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            Integer corrects) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, dated);
        requireNotRetired(person, dated);
        Integer corrected = correctedNumber(sheetId, personId, amount, corrects);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, noteOf(note), corrected));
        audit(sheetId, user, "CLAIM_ADDED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Change a draft claim's amount, date and note; without a date it is dated the sheet's today. A
     * claim that is no longer a draft is refused (an open one is voided and a new one added instead),
     * as is one dated in a closed period, or moved into one.
     */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            Integer corrects) {
        sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited");
        }
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, claim.getDate());
        periods.requireOpenOn(sheetId, dated);
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        requireNotRetired(owner, dated);
        Integer corrected = correctedNumber(sheetId, owner.getId(), amount, corrects);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrected);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        audit(sheetId, user, "CLAIM_EDITED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a claim to its next status; a change its current status does not allow is refused, as is
     * settling it by the user who opened it, settling it by a clerk when its due is above the sheet's
     * clerk limit (or it has none while there is a limit), and any change to a claim dated in a closed
     * period.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        Sheet sheet = sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        periods.requireOpenOn(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (next == ClaimStatus.SETTLED) {
            requireMaySettle(sheet, user, person, claim);
        }
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        // Worked out while the claim is still open, so settling freezes its late charge in.
        BigDecimal settledDue = next == ClaimStatus.SETTLED ? figure(sheetId, person, claim) : null;
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            claim.setDue(settledDue);
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            default -> "CLAIM_VOIDED";
        };
        String suffix = next == ClaimStatus.SETTLED
                ? " due=" + (saved.getDue() == null ? "n/a" : saved.getDue().setScale(2).toPlainString())
                : "";
        audit(sheetId, user, event, person, saved, number, suffix);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
     * of their claims that count, a held person's open ones not among them; n/a when the grade in force
     * today has no rate in force then and none of those claims has a figure; late charges in) is recorded, and each claim that counts is bound to its
     * figure then (its late charge not bound: it keeps following the sheet's today), the others left unbound. Their claims, newest first.
     */
    @Transactional
    public List<Claim> statement(String sheetId, String user, long personId) {
        Sheet sheet = sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RollupService.Rollup before = rollups.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getPersonId().equals(personId))
                .toList();
        List<Claim> counting = theirs.stream().filter(c -> RollupService.counts(person, c)).toList();
        boolean rated = rates.findInForce(sheetId, person.gradeOn(sheet.getToday()), sheet.getToday()).isPresent();
        boolean anyFigure = false;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : theirs) {
            if (RollupService.counts(person, c)) {
                BigDecimal figure = figure(sheetId, person, c);
                if (figure != null) total = total.add(figure);
                anyFigure |= figure != null;
                c.bind(rollups.boundFigure(sheetId, person, c));
            } else {
                c.unbind();
            }
        }
        claims.saveAllAndFlush(theirs);
        BigDecimal dueTotal = rated || anyFigure ? total : null;
        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
                + " claims=" + counting.size());
        rollups.recordChanges(sheetId, user, before);
        return theirs;
    }

    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
    private BigDecimal figure(String sheetId, Person person, Claim claim) {
        return rollups.figure(sheetId, person, claim);
    }

    /**
     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
     * with a number (a voided one keeps it) ends with it.
     */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number) {
        audit(sheetId, user, event, person, claim, number, "");
    }

    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number,
            String suffix) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "") + suffix);
    }

    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a steward settles any. */
    private void requireMaySettle(Sheet sheet, String user, Person person, Claim claim) {
        BigDecimal limit = sheet.getClerkLimit();
        if (limit == null || settings.roleOf(sheet.getId(), user) == Role.STEWARD) {
            return;
        }
        BigDecimal due = figure(sheet.getId(), person, claim);
        if (due == null || due.compareTo(limit) > 0) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "A clerk cannot settle a claim whose due is above the clerk limit");
        }
    }

    /**
     * The number a claim of this amount corrects: none for one of 0.00 or more; a correction (a
     * negative amount) must name a settled claim of the same person, else it is refused.
     */
    private Integer correctedNumber(String sheetId, long personId, BigDecimal amount, Integer corrects) {
        if (amount.signum() >= 0) return null;
        boolean settled = corrects != null && claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .anyMatch(c -> c.getPersonId() == personId && corrects.equals(c.getNumber())
                        && c.getStatus() == ClaimStatus.SETTLED);
        if (!settled) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A correction must name a settled claim of the same person");
        }
        return corrects;
    }

    /** Refuse a claim dated after the person's retirement. */
    private static void requireNotRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated after the person retired");
        }
    }

    private LocalDate dateOrToday(String sheetId, LocalDate date) {
        return date != null ? date : sheets.today(sheetId);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet makes. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** Given when the claim is opened; none while a draft; a voided claim keeps it (never reused). */
    @Column(name = "number")
    private Integer number;

    /** The user who opened the claim; none while a draft. They may not settle it. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Fixed when the claim is settled; none while live, or when its grade had no rate then (it stays live). */
    @Column(name = "due", precision = 15, scale = 2)
    private BigDecimal due;

    /** Bound by its person's last statement: it shows and totals {@code statedDue} until the next one. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim had at its person's last statement, when bound; none when it was n/a. */
    @Column(name = "stated_due", precision = 15, scale = 2)
    private BigDecimal statedDue;

    /** A correction's (negative amount) number of the settled claim of the same person it corrects; none otherwise. */
    @Column(name = "corrects")
    private Integer corrects;

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, Integer corrects) {
        this.corrects = corrects;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getAmount() { return amount; }

    public void setAmount(BigDecimal amount) { this.amount = amount; }

    public LocalDate getDate() { return date; }

    public void setDate(LocalDate date) { this.date = date; }

    public String getNote() { return note; }

    public void setNote(String note) { this.note = note; }

    public ClaimStatus getStatus() { return status; }

    public void setStatus(ClaimStatus status) { this.status = status; }

    public Integer getNumber() { return number; }

    public void setNumber(Integer number) { this.number = number; }

    public String getOpenedBy() { return openedBy; }

    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public BigDecimal getDue() { return due; }

    public void setDue(BigDecimal due) { this.due = due; }

    public Integer getCorrects() { return corrects; }

    public void setCorrects(Integer corrects) { this.corrects = corrects; }

    /** A correction: a negative amount; its due has no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public boolean isStated() { return stated; }

    public BigDecimal getStatedDue() { return statedDue; }

    /** Whether the claim keeps a figure that does not follow the rates: a settled due, or a bound one (not n/a). */
    public boolean keepsFigure() {
        return due != null || (stated && statedDue != null);
    }

    /** Bind the claim to this figure (null: n/a). */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Leave the claim unbound: its figure is live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The sheet's settings (its clerk limit, floor, terms and late percent) and the roles it gives user names. */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, SheetService sheets, RollupService rollups, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's settings now. */
    @Transactional
    public Sheet settings(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
     * {@code floor} the floor, a non-null {@code terms} the terms in days, a non-null {@code latePct} the
     * late percent; each one saved is audited, even when its value is the same. A floor, terms or late
     * percent that moves dues records the rollups that moved.
     */
    @Transactional
    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
            Integer terms, BigDecimal latePct) {
        Sheet sheet = sheets.lock(sheetId, user);
        if (setClerkLimit) {
            sheet.setClerkLimit(clerkLimit);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
        }
        if (floor != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setFloor(floor);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=floor value=" + floor.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        if (terms != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setTerms(terms);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=terms value=" + terms);
            rollups.recordChanges(sheetId, user, before);
        }
        if (latePct != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setLatePct(latePct);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=late-pct value=" + latePct.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        return sheet;
    }

    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role the sheet gives a user name; clerk when it gives none. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
        sheets.lock(sheetId, user);
        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        entry.setRole(role);
        SheetRole saved = roles.saveAndFlush(entry);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + userName + " role=" + role.name().toLowerCase());
        return saved;
    }
}
