export class Settings {
  protected readonly settings = inject(SettingsService);
  private readonly sheets = inject(SheetService);
  protected readonly roles = ROLES;
  protected readonly settingsForm = new FormGroup({
    clerkLimit: new FormControl('', { nonNullable: true }),
    floor: new FormControl('', { nonNullable: true }),
    terms: new FormControl('', { nonNullable: true }),
    latePct: new FormControl('', { nonNullable: true }),
  });
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });
  protected readonly settingsError = signal('');
  protected readonly roleError = signal('');
  /** A submit is waiting for its answer; another submit of the same form meanwhile is ignored. */
  private savingSettings = false;
  private savingRole = false;

  constructor() {
    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
    effect(() => {
      this.sheets.loads();
      untracked(() => {
        this.settingsError.set('');
        this.roleError.set('');
        this.resetSettings();
        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
      });
    });
  }

  protected save(): void {
    if (this.savingSettings) return;
    this.settingsError.set('');
    const { clerkLimit, floor, terms, latePct } = this.settingsForm.controls;
    const limit = clerkLimit.value.trim();
    const least = floor.value.trim();
    const days = terms.value.trim();
    const late = latePct.value.trim();
    if (limit !== '' && !/^\d{1,13}(\.\d{1,2})?$/.test(limit)) {
      this.settingsError.set('Enter a clerk limit of 0.00 or more with up to two decimals, or leave it empty.');
      return;
    }
    if (!/^\d{1,13}(\.\d{1,2})?$/.test(least)) {
      this.settingsError.set('Enter a floor of 0.00 or more with up to two decimals.');
      return;
    }
    if (!/^\d{1,4}$/.test(days)) {
      this.settingsError.set('Enter terms of 0 or more whole days.');
      return;
    }
    if (!/^\d{1,3}(\.\d{1,2})?$/.test(late)) {
      this.settingsError.set('Enter a late percent of 0.00 or more with up to two decimals.');
      return;
    }
    // Only the settings the user changed or filled in are saved (and audited).
    const change: SettingsChange = {};
    if (clerkLimit.dirty || clerkLimit.touched) change.clerkLimit = limit;
    if (floor.dirty || floor.touched) change.floor = least;
    if (terms.dirty || terms.touched) change.terms = days;
    if (latePct.dirty || latePct.touched) change.latePct = late;
    this.savingSettings = true;
    this.settings.save(change).pipe(finalize(() => (this.savingSettings = false))).subscribe({
      next: () => this.resetSettings(),
      error: () => this.settingsError.set('Could not save the settings.'),
    });
  }

  private resetSettings(): void {
    this.settingsForm.reset(
      { clerkLimit: this.settings.clerkLimit() ?? '', floor: this.settings.floor(),
        terms: String(this.settings.terms()), latePct: this.settings.latePct() },
      { emitEvent: false },
    );
  }

  protected setRole(): void {
    if (this.savingRole) return;
    this.roleError.set('');
    const { user, role } = this.roleForm.getRawValue();
    const u = user.trim();
    const r = role.trim();
    if (!u) {
      this.roleError.set('Enter a user name.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(r)) {
      this.roleError.set(`Enter a role: ${ROLES.join(' or ')}.`);
      return;
    }
    this.savingRole = true;
    this.settings.setRole(u, r).pipe(finalize(() => (this.savingRole = false))).subscribe({
      next: () => this.roleForm.reset({ user: '', role: '' }, { emitEvent: false }),
      error: () => this.roleError.set('Could not set that role.'),
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, forkJoin, of, tap } from 'rxjs';
import { LateTerms, cents } from './claims.service';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export type Role = 'clerk' | 'steward';

export const ROLES: readonly Role[] = ['clerk', 'steward'];

export interface RoleEntry {
  user: string;
  role: Role;
}

interface SettingsView {
  /** Two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** Two decimals: a claim's live due is at least this. */
  floor: string;
  /** Days: a claim is due by its date plus these. */
  terms: number;
  /** Two decimals: an overdue claim gains this percent of its figure for every full 30 days overdue. */
  latePct: string;
}

/** The settings to save; one left out keeps its value. The clerk limit is '' for no limit. */
export interface SettingsChange {
  clerkLimit?: string;
  floor?: string;
  terms?: string;
  latePct?: string;
}

/** The floor a sheet starts with. */
const DEFAULT_FLOOR = '1.00';

/** The terms (days) a sheet starts with. */
const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
const DEFAULT_LATE_PCT = '0.00';

// The active sheet's settings and the roles it gives user names. A name with no role is a clerk; a
// clerk may settle a claim only when its due is at or below the clerk limit (none: no limit), a
// steward any claim. A claim's live due is at least the floor; it is due by its date plus the terms;
// an overdue one gains the late percent of its figure for every full 30 days overdue.
@Injectable({ providedIn: 'root' })
export class SettingsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly limit = signal<string | null>(null);
  private readonly floorValue = signal<string>(DEFAULT_FLOOR);
  private readonly termsValue = signal<number>(DEFAULT_TERMS);
  private readonly latePctValue = signal<string>(DEFAULT_LATE_PCT);
  private readonly list = signal<RoleEntry[]>([]);

  readonly clerkLimit = this.limit.asReadonly();
  readonly floor = this.floorValue.asReadonly();
  /** The floor in cents. */
  readonly floorCents = computed(() => cents(this.floorValue()));
  /** The terms in days. */
  readonly terms = this.termsValue.asReadonly();
  readonly latePct = this.latePctValue.asReadonly();
  /** The late percent in hundredths of a percent. */
  readonly latePctHundredths = computed(() => cents(this.latePctValue()));
  readonly roles = this.list.asReadonly();
  /** What an overdue claim's late charge follows now. */
  readonly late = computed<LateTerms>(() => ({
    terms: this.termsValue(), today: this.sheets.today(), pct: this.latePctHundredths(),
  }));

  /** Re-read the active sheet's settings and roles from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.limit.set(null);
      this.floorValue.set(DEFAULT_FLOOR);
      this.termsValue.set(DEFAULT_TERMS);
      this.latePctValue.set(DEFAULT_LATE_PCT);
      this.list.set([]);
      return of(null);
    }
    const headers = this.session.headers();
    return forkJoin([
      this.http.get<SettingsView>(`${this.url(id)}/settings`, { headers }),
      this.http.get<RoleEntry[]>(`${this.url(id)}/roles`, { headers }),
    ]).pipe(tap(([settings, roles]) => {
      if (this.sheets.sheetId() !== id) return;
      this.set(settings);
      this.list.set(roles);
    }));
  }

  /** Save the settings given (the others keep their values). */
  save(change: SettingsChange): Observable<SettingsView> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<SettingsView>(`${this.url(id)}/settings`, change, { headers: this.session.headers() })
      .pipe(tap((s) => this.set(s)));
  }

  private set(settings: SettingsView): void {
    this.limit.set(settings.clerkLimit);
    this.floorValue.set(settings.floor);
    this.termsValue.set(settings.terms);
    this.latePctValue.set(settings.latePct);
  }

  /** Give a user name a role, replacing the one it had; refused for any role but clerk or steward. */
  setRole(user: string, role: string): Observable<RoleEntry> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<RoleEntry>(`${this.url(id)}/roles`, { user, role }, { headers: this.session.headers() })
      .pipe(tap((r) => this.list.update((all) => [...all.filter((o) => o.user !== r.user), r]
        .sort((a, b) => a.user.localeCompare(b.user)))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}
